INSERT INTO "revisions" VALUES('a6542bb80741f264a6cbf393b2112f816be8d9b2cf0723f9a9d078ffc7dde346','legacy_stream_names','{"entry":"main.nex","files":{"main.nex":"module legacy_stream_names;\nfn identity<file>(value:file)->file{return value;}\nfn file_open_append(value:bytes)->bytes{return value;}\nfn file_size(value:bytes)->bytes{return value;}\nfn file_flush(value:bytes)->bytes{return value;}\nfn file_is_open(value:bytes)->bool{return len(value)>0;}\nfn main()->unit!{io}{\n let data:bytes=identity(file_flush(file_size(file_open_append(utf8_bytes(\"Я🧠\")))));\n print(encode_base64(data));print(file_is_open(data));\n}\ntest fn preserved_names()->unit{\n assert(identity(file_flush(file_size(file_open_append(utf8_bytes(\"text\")))))==utf8_bytes(\"text\"));\n assert(!file_is_open(utf8_bytes(\"\")));\n}\n"},"schema":"nex.sources/1"}','/Users/sae/projects/NEX/build/language-013-stream-names-capture/main.nex','2026-10-18T06:24:15.191Z','0.13');
